<div class="col-12"><label for="fundo" class="form-label">Imagem de fundo</label><input id="fundo" name="fundo" type="file" class="form-control" accept=".png,.jpg,.jpeg,image/png,image/jpeg"><div class="form-text">PNG, JPG ou JPEG, até 10 MB.</div><input id="remover_fundo" name="remover_fundo" type="hidden" value="0">@if($template->fundo&&!$backgroundExists)<div class="alert alert-warning mt-2">O arquivo <strong>{{ $template->fundo }}</strong> não foi encontrado.</div>@endif<div id="previewArea" class="mt-3 {{ $backgroundExists?'':'d-none' }}"><img id="preview" class="background-preview border rounded" @if($backgroundExists) src="{{ $template->backgroundUrl() }}" @endif alt="Imagem de fundo"><div><button id="removeImage" type="button" class="btn btn-sm btn-outline-danger mt-2"><i class="bi bi-x-lg me-1"></i>Remover fundo</button></div></div></div>
