@push('scripts')<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{$('#certificado_a1').select2({theme:'bootstrap-5',width:'100%',placeholder:'Pesquise por ID ou nome',allowClear:true,ajax:{url:@json(route('templates.certificados-a1',[],false)),dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:r=>r}});const pagina=document.getElementById('pagina'),layout=document.getElementById('layout_pagina'),dimensions=document.getElementById('customDimensions'),width=document.getElementById('largura'),height=document.getElementById('altura'),sizes={A4:[210,297],Carta:[216,279],Oficio:[216,356]};const updateDimensions=()=>{const custom=pagina.value==='Personalizado';dimensions.classList.toggle('d-none',!custom);if(!custom&&sizes[pagina.value]){const [w,h]=sizes[pagina.value],landscape=layout.value==='Paisagem';width.value=landscape?h:w;height.value=landscape?w:h}else if(custom&&(!width.value||!height.value)){width.value=layout.value==='Paisagem'?297:210;height.value=layout.value==='Paisagem'?210:297}};pagina.addEventListener('change',updateDimensions);layout.addEventListener('change',updateDimensions);updateDimensions();const input=document.getElementById('fundo'),area=document.getElementById('previewArea'),preview=document.getElementById('preview'),flag=document.getElementById('remover_fundo');let url=null;input.addEventListener('change',()=>{const file=input.files[0];if(!file)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(file);preview.src=url;area.classList.remove('d-none');flag.value='0'});document.getElementById('removeImage').addEventListener('click',()=>{if(url)URL.revokeObjectURL(url);url=null;input.value='';preview.removeAttribute('src');area.classList.add('d-none');flag.value='1'})});</script>@endpush
